internal static class DpsVerification {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void V(List<byte> b,uint v){while(v>=128){b.Add((byte)((v&127)|128));v>>=7;}b.Add((byte)v);}
    static byte[] Hit(uint source,uint amount,bool extras,uint target=99){var b=new List<byte>(new byte[]{4,0x38});V(b,target);V(b,extras?38u:6u);V(b,0);V(b,source);b.AddRange(BitConverter.GetBytes(15210000));b.Add(1);V(b,2);b.AddRange(new byte[]{128,0,1,85,102,119,136,1,0,0,0});V(b,10817);V(b,amount);if(extras){V(b,2);V(b,11);V(b,11);}b.AddRange(new byte[]{1,0});return b.ToArray();}
    static byte[] Identity(uint actor,string name){var b=new List<byte>(new byte[]{4,0x8d,1,0,0,0,0});V(b,actor);b.AddRange(new byte[]{1,0,(byte)name.Length});b.AddRange(Encoding.UTF8.GetBytes(name));return b.ToArray();}
    static byte[] Energy(uint actor){var b=new List<byte>(new byte[]{0,0x8d});V(b,actor);b.AddRange(new byte[]{1,1,3});b.AddRange(BitConverter.GetBytes(1000));return b.ToArray();}
    static byte[] Spawn(uint actor,uint parent){var b=new List<byte>(new byte[]{0x41,0x36});V(b,actor);b.AddRange(new byte[]{31,0,0});b.AddRange(BitConverter.GetBytes(2920551));b.AddRange(BitConverter.GetBytes((ushort)576));b.AddRange(new byte[19]);V(b,1000);V(b,1000);b.AddRange(new byte[54]);V(b,1);b.Add(17);V(b,1);b.AddRange(BitConverter.GetBytes(1));b.AddRange(new byte[16]);V(b,actor);b.AddRange(new byte[]{1,2});b.AddRange(new byte[15]);b.AddRange(BitConverter.GetBytes(parent));V(b,2);b.AddRange(new byte[16]);V(b,0);return b.ToArray();}
    static byte[] Tick(uint source,byte flags,uint skill,uint amount){var b=new List<byte>(new byte[]{5,0x38});V(b,99);b.Add(flags);V(b,source);V(b,1);b.AddRange(BitConverter.GetBytes(1539000011));if((flags&1)!=0)V(b,1000);if((flags&2)!=0)V(b,amount);if((flags&8)!=0)b.AddRange(BitConverter.GetBytes(skill));return b.ToArray();}
    static byte[] Member(uint actor,string name,uint code=26){var b=new List<byte>();b.AddRange(BitConverter.GetBytes(actor));b.AddRange(BitConverter.GetBytes((ushort)1301));b.AddRange(BitConverter.GetBytes((ushort)1301));b.Add(36);b.AddRange(Encoding.ASCII.GetBytes("00000000-0000-0000-0000-000000000000"));b.AddRange(new byte[6]);b.AddRange(BitConverter.GetBytes((ushort)1301));b.Add((byte)name.Length);b.AddRange(Encoding.UTF8.GetBytes(name));b.AddRange(BitConverter.GetBytes(code));b.AddRange(new byte[12]);return b.ToArray();}
    static byte[] Party(bool friend){var b=new List<byte>(new byte[]{0,0x92,8});b.AddRange(Member(42,"Alpha"));if(friend)b.AddRange(Member(43,"Beta",33));return b.ToArray();}
    static byte[] Vital(uint actor){var b=new List<byte>(new byte[]{0x1b,0x92});V(b,actor);V(b,9000);V(b,10000);b.AddRange(BitConverter.GetBytes(2000u));b.AddRange(BitConverter.GetBytes(3000u));b.AddRange(new byte[16]);b.Add(1);return b.ToArray();}
    static byte[] Npc(uint actor){var b=new List<byte>(new byte[]{0x41,0x36});V(b,actor);b.AddRange(new byte[]{0,0,0,1,0,0,0});return b.ToArray();}
    static void Feed(DpsSignal signal,byte[] frame,double ts){signal.Consume(frame,0,frame.Length,ts,"test-stream");}
    internal static void Run(string root){
        DpsSignal.Hit e;byte[] hit=Hit(42,1263,true);Check(DpsSignal.Direct(hit,0,hit.Length,out e)&&e.Amount==1263&&e.Extras==2,"Included additional impacts must not be added twice");
        for(int end=0;end<hit.Length-2;end++)Check(!DpsSignal.Direct(hit,0,end,out e),"Truncated hit must fail closed");
        byte[] tick=Tick(98,10,15390002,194);Check(DpsSignal.Periodic(tick,0,tick.Length,out e)&&e.Amount==194,"Fire Wall current impact");
        byte[] heal=Tick(98,11,2011101,420);Check(!DpsSignal.Periodic(heal,0,heal.Length,out e),"Potion remaining and healing must never enter DPS");
        for(int end=0;end<tick.Length;end++)Check(!DpsSignal.Periodic(tick,0,end,out e),"Truncated periodic impact");
        uint actor,parent;byte[] spawn=Spawn(98,42);Check(DpsSignal.EffectParent(spawn,0,spawn.Length,out actor,out parent)&&actor==98&&parent==42,"Explicit effect parent");
        for(int end=0;end<spawn.Length;end++)Check(!DpsSignal.EffectParent(spawn,0,end,out actor,out parent),"Partial spawn must not give a parent");
        var signal=new DpsSignal();var o=new DpsOptions{Enabled=true,Scope="global"};signal.Configure(o);Feed(signal,Energy(42),1);Feed(signal,Identity(42,"Alpha"),1);Feed(signal,Identity(43,"Beta"),1);
        var npc=new List<byte>(new byte[]{0x41,0x36});V(npc,99);npc.AddRange(new byte[]{0,0,0,1,0,0,0});Feed(signal,npc.ToArray(),1);Feed(signal,spawn,1);
        Feed(signal,Hit(98,1263,true),2);Feed(signal,Hit(43,400,false),3);Feed(signal,tick,4);Feed(signal,heal,4);
        var s=signal.Read(4);Check(s.Rows.Count==2&&s.Rows[0].Damage==1457&&s.Rows[0].Hits==4,"Supported DoT is automatic and effect ownership remains attributed");
        double shared=s.Duration;o.Scope="self";signal.Configure(o);s=signal.Read(4);Check(s.Rows.Count==1&&s.Rows[0].Name=="Alpha"&&s.Duration==shared&&s.LastImpact==4,"Self filter retains duration, uses its own activity for hiding");
        Feed(signal,Hit(99,100,false,42),4);s=signal.Read(4);Check(s.LastImpact==4&&s.Rows[0].Damage==1457,"Incoming attacks keep the selected player active without increasing DPS");
