        var delta=new List<byte>(new byte[]{0x0d,0x92,0,2});delta.AddRange(Member(43,"Beta",33));Feed(signal,delta.ToArray(),5.1);s=signal.Read(5.1);Check(s.PartyKnown&&s.Rows.Count==2,"Single-member join update must append to the party");
        Feed(signal,Party(false),5.2);Check(signal.Read(5.2).Rows.Count==1,"Full roster replaces a prior incremental join");
        o.Scope="global";signal.Configure(o);Check(signal.Read(5.2).Rows.Count==2,"Party filter must not erase global totals");
        signal.ResetEncounter();Feed(signal,tick,6);Check(signal.Read(6).Rows[0].Damage==194&&signal.Read(6).Rows[0].PeriodicDamage==194,"Manual reset clears totals and supported ticks resume without a setting");
        Feed(signal,heal,7);Check(signal.Read(7).Rows[0].Damage==194,"Healing must not change damage");Feed(signal,Hit(42,100,false),20);Check(signal.Read(20).Rows[0].Damage==100,"Idle gap starts new encounter");
        signal.ResetEncounter();Check(signal.Read(20).Rows.Count==0,"Manual reset");Feed(signal,Hit(98,200,false),130);Check(signal.Read(130).Rows.Count==0,"Stale entities expire after traffic gap");
        var random=new Random(31);for(int n=0;n<10000;n++){var bytes=new byte[random.Next(0,140)];random.NextBytes(bytes);DpsSignal.Direct(bytes,0,bytes.Length,out e);DpsSignal.Periodic(bytes,0,bytes.Length,out e);DpsSignal.EffectParent(bytes,0,bytes.Length,out actor,out parent);signal.Consume(bytes,0,bytes.Length,200+n*.01,"test-stream");}
        var serializer=new JavaScriptSerializer();o.Color="#123456";o.Bounds=new Rectangle(20,30,400,250);var restored=DpsOptions.Read(serializer.Deserialize<Dictionary<string,object>>(serializer.Serialize(new{dps=o})));Check(DpsOptions.Same(o,restored)&&!DpsOptions.Read(new Dictionary<string,object>()).Enabled,"Settings migration/persistence");
        VerifyTargetRecovery();VerifyHitTags();VerifyCombatMetrics();VerifyHistory(root);VerifyIndividualDeletion(root);VerifyMinimumDuration(root);VerifyPartyRecovery();VerifyDungeonTransition();VerifySelfDisplay();VerifyMotion();Check(DpsSignal.RoleFromWire(9)==3&&DpsSignal.RoleFromWire(26)==1&&DpsSignal.RoleFromWire(33)==2&&DpsSignal.RoleFromWire(999)==0,"Wire role mapping");
        string designs=Path.Combine(root,"designs");Directory.CreateDirectory(designs);using(var w=new DpsPaintWorkspace()){
            using(var b=DpsDesign.Render(380,220,DpsDesign.Sample(),new DpsOptions(),false,"en",w)){Check(b.GetPixel(0,0).A==0&&b.GetPixel(20,20).A>0,"Transparent rounded panel");b.Save(Path.Combine(designs,"dps-widget-en.png"));}
            using(var b=DpsDesign.Render(380,220,DpsDesign.Sample(),new DpsOptions(),false,"es",w))b.Save(Path.Combine(designs,"dps-widget-es.png"));
            foreach(string view in new[]{"damage","healing","received"}){var metrics=new DpsOptions{View=view};using(var b=DpsDesign.Render(578,241,DpsDesign.Sample(metrics),metrics,false,"es",w))b.Save(Path.Combine(designs,"dps-metrics-"+view+"-es.png"));using(var b=DpsDesign.Render(260,220,DpsDesign.Sample(metrics),metrics,false,"en",w))b.Save(Path.Combine(designs,"dps-metrics-"+view+"-small.png"));}
            var five=DpsDesign.Sample();five.Rows.Add(new DpsSignal.Row{Actor=4,Name="Player Four",Role=1,Damage=15000,Dps=600});five.Rows.Add(new DpsSignal.Row{Actor=5,Name="Player Five",Role=3,Damage=10000,Dps=400});foreach(var size in new[]{new Size(578,241),new Size(260,110)})using(var b=DpsDesign.Render(size.Width,size.Height,five,new DpsOptions(),false,"es",w)){int header=DpsDesign.HeaderHeight(size.Width),footer=DpsDesign.FooterHeight(size.Width,size.Height),line=Math.Max(21,(size.Height-header-footer)/6),row=size.Height==110?1:5;Check(b.GetPixel(20,header+(row+1)*line-3).ToArgb()==ColorTranslator.FromHtml(row==5?"#4A92E4":"#E05252").ToArgb(),"Tabs must preserve rows at "+size+" pixel="+b.GetPixel(20,header+(row+1)*line-3));b.Save(Path.Combine(designs,"dps-tabs-"+size.Width+"x"+size.Height+"-es.png"));}
            using(var b=DpsDesign.Render(380,220,new DpsSignal.Snapshot{NeedsIdentification=true,Status="Dash once to identify your character"},new DpsOptions(),false,"es",w))b.Save(Path.Combine(designs,"dps-detection-es.png"));
            var personal=new DpsOptions{ShowSelfAsYou=true,PinSelfFirst=true};using(var b=DpsDesign.Render(380,220,DpsDesign.Sample(personal),personal,false,"es",w))b.Save(Path.Combine(designs,"dps-self-first-es.png"));
            var sample=DpsDesign.Sample();var style=new DpsOptions();w.ReplacePanel(DpsDesign.Render(380,220,sample,style,false,"en",w,null,false));int barY=DpsDesign.HeaderHeight(380)+2*((220-DpsDesign.HeaderHeight(380)-25)/(style.MaxRows+1))-3;Color empty=w.Panel.GetPixel(20,barY);var ratios=new Dictionary<uint,double>{{1,.5},{2,.25},{3,.1}};using(var b=DpsDesign.Compose(w,sample,style,ratios)){Check(b.GetPixel(20,barY).ToArgb()==ColorTranslator.FromHtml(style.DamageColor).ToArgb()&&b.GetPixel(300,barY).ToArgb()==w.Panel.GetPixel(300,barY).ToArgb()&&w.Panel.GetPixel(20,barY).ToArgb()==empty.ToArgb(),"Animated bars reuse an unchanged text/background panel");}
        }
        var palette=new DpsOptions{DamageColor="#CC1122",HealerColor="#22AA33",TankColor="#3344BB"};Check(DpsDesign.RowColor(new DpsSignal.Row{Role=1},palette)==ColorTranslator.FromHtml(palette.DamageColor)&&DpsDesign.RowColor(new DpsSignal.Row{Role=2},palette)==ColorTranslator.FromHtml(palette.HealerColor)&&DpsDesign.RowColor(new DpsSignal.Row{Role=3},palette)==ColorTranslator.FromHtml(palette.TankColor),"Custom role palette");palette.RoleColors=false;Check(DpsDesign.RowColor(new DpsSignal.Row{Role=3},palette)==ColorTranslator.FromHtml(palette.Color),"Disable role colors preserves custom fallback");
        Check(DpsDesign.Resize(new Rectangle(10,20,380,220),new Point(1000,1000),13)==new Rectangle(130,130,260,110),"Resize minimum preserves opposite corner");
        var area=new Rectangle(0,0,2560,1552);var fitted=DpsDesign.Constrain(new Rectangle(1615,1356,578,241),area);Check(area.Contains(fitted)&&fitted.Bottom==1552&&fitted.Width==578&&fitted.Height==241,"Unlocked DPS must leave the bottom taskbar accessible");area=new Rectangle(-1920,40,1880,1040);Check(area.Contains(DpsDesign.Constrain(new Rectangle(-300,-10,578,241),area)),"Taskbar boundary supports negative monitor positions and top/side taskbars");
        var screen=System.Windows.Forms.Screen.PrimaryScreen;File.WriteAllText(Path.Combine(root,"dps-workarea-test.txt"),"Screen: "+screen.Bounds+"; Working area: "+screen.WorkingArea+"; safe DPS: "+DpsDesign.UsableBounds(new Rectangle(screen.Bounds.Right-578,screen.Bounds.Bottom-241,578,241)));
        using(var owner=new EnergyOverlay(root,true)){using(var widget=new DpsOverlay(owner,new DpsSignal(),true)){widget.VerifyCache();widget.VerifyTabs();}var settings=new HelperSettings(owner);try{settings.VerifyDps(root);}finally{settings.Close();}var pane=new DpsSettingsPane(owner,null);pane.VerifyIdentityOptions();pane.VerifyCombatView();pane.VerifyHistory();}
        File.WriteAllText(Path.Combine(root,"dps-test.txt"),"PASS: captured Front/Back/Double/Perfect and combinations, variable restoration, metadata absence; per-player primary peak/ticks, immutable metrics and legacy unknowns; sixty-second history filter/boundaries/disable/persistence/no short-fight disk writes; damage parsing; explicit ownership; automatic identified DoT; healing done/received/self/HoT/HPS and exclusions; primary critical amount share versus observed frequency; no extra-impact/periodic crit guessing; legacy toggle migration; combat views/sorting/pinning/undo and native locked tabs; immutable per-player history; exactly-once idle/reset/transport completion; persistent/atomic saves; retention/oldest eviction; individual/all deletion; filtered localized TXT; history UI; scoped activity; party full/delta/deferred/startup recovery and expiry/leave; persistent dash notice; localized self display; wire roles/custom colors; fade reversal/idle hide/unlocked visibility; smooth growth/shrink and disable; reset/expiry; malformed inputs; persistence; resize; EN/ES UI; disabled controls; render/resource cache.");
    }
    static byte[] MetricHit(uint source,uint target,uint amount,uint skill,bool critical,bool extras=false,byte tags=128,byte position=1,uint restoration=0,bool metadata=true){var b=new List<byte>(new byte[]{4,0x38});V(b,target);V(b,(extras?36u:4u)|(metadata?2u:0u));V(b,0);V(b,source);b.AddRange(BitConverter.GetBytes(skill));b.Add(1);V(b,critical?3u:2u);if(metadata){b.Add(tags);V(b,restoration);b.Add(position);}b.AddRange(new byte[]{85,102,119,136,1,0,0,0});V(b,10817);V(b,amount);if(extras){V(b,2);V(b,11);V(b,11);}b.AddRange(new byte[]{1,0});return b.ToArray();}
    static byte[] MetricTick(uint source,uint target,uint amount,uint skill,uint effect,byte flags=10){var b=new List<byte>(new byte[]{5,0x38});V(b,target);b.Add(flags);V(b,source);V(b,1);b.AddRange(BitConverter.GetBytes(effect));if((flags&1)!=0)V(b,9999);if((flags&2)!=0)V(b,amount);if((flags&8)!=0)b.AddRange(BitConverter.GetBytes(skill));return b.ToArray();}
    static DpsSignal.Row Find(DpsSignal.Snapshot s,uint actor){foreach(var row in s.Rows)if(row.Actor==actor)return row;throw new Exception("Missing metrics actor");}
    internal static DpsHistoryRecord HistorySample(double timestamp,double duration=24.5){var s=DpsDesign.Sample();var r=new DpsHistoryRecord{Id=Guid.NewGuid().ToString("N"),Started=timestamp-duration,Ended=timestamp,Duration=duration,Reason="Inactivity",Scope="party",SelfActor=2,Map=600021,PartyKnown=true,Party=new List<uint>{1,2,3}};foreach(var p in s.Rows)r.Players.Add(DpsHistoryPlayer.Capture(p,p.Name,p.Role,r.Duration));return r;}
    static byte[] Hex(string value){var result=new byte[value.Length/2];for(int i=0;i<result.Length;i++)result[i]=Convert.ToByte(value.Substring(i*2,2),16);return result;}
    static byte[] TargetHp(uint actor,long hp){var b=new List<byte>(new byte[]{0,0x8d});V(b,actor);b.AddRange(new byte[]{2,1,0});b.AddRange(BitConverter.GetBytes(hp));return b.ToArray();}
    static void VerifyTargetRecovery(){
        var signal=new DpsSignal();signal.Configure(new DpsOptions{Enabled=true,Scope="self"});Feed(signal,Energy(42),1);
        Feed(signal,TargetHp(99,10000),2);Feed(signal,MetricHit(42,99,100,15210000,false,position:2),2.1);
        Check(signal.Read(2.1).Rows.Count==0,"Unknown target needs subsequent HP evidence");Feed(signal,TargetHp(99,9550),2.1);
        Check(Find(signal.Read(2.1),42).Damage==100&&signal.Read(2.1).Npcs==0&&signal.Read(2.1).RecoveredImpacts==1,"Restart recovery retains announced damage without inventing NPC identity or HP scaling");
        Feed(signal,MetricHit(42,99,150,15210000,false,position:1),2.2);Feed(signal,TargetHp(99,9600),2.2);Check(Find(signal.Read(2.2),42).Damage==100,"Healing HP increases cannot confirm damage");
        Feed(signal,MetricHit(42,99,200,15210000,false,metadata:false),2.3);Feed(signal,TargetHp(99,9000),2.3);Check(Find(signal.Read(2.3),42).Damage==100,"Untagged unknown effects cannot confirm damage");
        Feed(signal,MetricHit(42,99,300,18120000,false,position:2),2.4);Feed(signal,TargetHp(99,8000),2.4);Check(Find(signal.Read(2.4),42).Damage==100,"Known heals remain excluded from recovery");
        Feed(signal,MetricHit(42,99,400,15210000,false,position:2),3);Feed(signal,TargetHp(99,7000),3);Check(Find(signal.Read(3),42).Damage==100,"Stale target HP cannot confirm damage");
        Feed(signal,Identity(99,"Beta"),3.1);Feed(signal,TargetHp(99,6000),3.2);Feed(signal,MetricHit(42,99,500,15210000,false,position:2),3.3);Feed(signal,TargetHp(99,5000),3.3);Check(Find(signal.Read(3.3),42).Damage==100,"Player identity invalidates target recovery");
        signal.ResetTransport();Feed(signal,Energy(42),4);Feed(signal,MetricHit(42,99,600,15210000,false,position:2),4.1);Feed(signal,TargetHp(99,4000),4.1);Check(signal.Read(4.1).Rows.Count==0,"Flow reset removes recovery evidence");
        var smallDrop=new DpsSignal();smallDrop.Configure(new DpsOptions{Enabled=true,Scope="self"});Feed(smallDrop,Energy(42),1);Feed(smallDrop,TargetHp(99,1000),2);Feed(smallDrop,MetricHit(42,99,500,15210000,false),2.1);Feed(smallDrop,TargetHp(99,999),2.1);Check(smallDrop.Read(2.1).Rows.Count==0,"Unrelated small HP drop cannot confirm large impact");
    }
    static void VerifyHitTags(){
        DpsSignal.Hit decoded;var real=Hex("0438CED1013600D805E4D012015C038800021B99596B010000009E55E52404D603D603D603D6030100");
        Check(DpsSignal.Direct(real,0,real.Length,out decoded)&&decoded.TagsKnown&&decoded.Position==2&&decoded.Double&&!decoded.Perfect&&decoded.Critical&&decoded.Amount==4709&&decoded.PrimaryAmount==2829,"Captured Front Double Critical retains its original amounts");
        real=Hex("0438CED1013600D805E4D0120171038400010D20596B020000009E55F21103E501E501E5010200");
        Check(DpsSignal.Direct(real,0,real.Length,out decoded)&&decoded.TagsKnown&&decoded.Position==1&&decoded.Perfect&&!decoded.Double&&decoded.Critical,"Captured Back Perfect Critical metadata");
        var variable=MetricHit(42,99,1000,15210000,true,false,12,2,16384);Check(DpsSignal.Direct(variable,0,variable.Length,out decoded)&&decoded.TagsKnown&&decoded.Double&&decoded.Perfect&&decoded.Position==2,"Restoration varint length must not shift hit tags");
        var unknown=MetricHit(42,99,900,15210000,false,false,4,7);Check(DpsSignal.Direct(unknown,0,unknown.Length,out decoded)&&!decoded.TagsKnown&&decoded.Amount==900,"Unknown position keeps damage without fabricated tags");
        var missing=MetricHit(42,99,800,15210000,false,false,0,0,0,false);Check(DpsSignal.Direct(missing,0,missing.Length,out decoded)&&!decoded.TagsKnown&&decoded.Amount==800,"Absent plotter is unavailable rather than a zero positional count");
        for(int end=0;end<variable.Length-2;end++)Check(!DpsSignal.Direct(variable,0,end,out decoded),"Truncated tagged damage fails closed");
        var reader=new DpsSignal();reader.Configure(new DpsOptions{Enabled=true,Scope="global"});Feed(reader,Energy(42),1);Feed(reader,Identity(42,"Alpha"),1);Feed(reader,Identity(43,"Beta"),1);Feed(reader,Npc(99),1);
        Feed(reader,MetricHit(42,99,1000,15210000,true,false,8,1),2);Feed(reader,MetricHit(42,99,300,15210000,false,false,4,2),3);Feed(reader,MetricHit(42,99,700,15210000,true,false,4,1),4);Feed(reader,MetricHit(42,99,500,15210000,false,false,8,0),5);Feed(reader,unknown,6);Feed(reader,missing,7);
        var row=Find(reader.Read(7),42);Check(row.Damage==4200&&row.HighestHit==1000&&row.TaggedDamageEvents==4&&row.BackHits==2&&row.FrontHits==1&&row.DoubleHits==2&&row.PerfectHits==2&&row.BackCriticalHits==2&&row.BackDoubleCriticalHits==1&&row.BackPerfectHits==1&&row.FrontPerfectHits==1,"Per-player overlapping tag counts must exclude missing/unknown metadata");
        Feed(reader,MetricHit(43,99,250,15210000,true,false,8,2),7.1);Check(Find(reader.Read(7.1),43).FrontDoubleCriticalHits==1&&Find(reader.Read(7.1),42).FrontDoubleCriticalHits==0,"Highest hit and combos are isolated per player");
        Feed(reader,MetricHit(42,99,2000,15210000,false,true,0,0),8);Check(Find(reader.Read(8),42).HighestHit==1978,"Largest primary hit must not include the summed extra impacts");Feed(reader,Tick(42,10,15390002,5000),9);Feed(reader,MetricHit(43,42,90000,18160002,true),9.1);row=Find(reader.Read(9.1),42);Check(row.HighestHit==5000&&row.TaggedDamageEvents==5,"Periodic tick contributes once to highest hit; healing does not add damage or tags");
        var archived=DpsHistoryPlayer.Capture(row,"Alpha",1,8);row.HighestHit=1;row.BackHits=100;Check(archived.HighestHit==5000&&archived.BackHits==2,"Archived peak and tags are immutable snapshots");reader.ResetEncounter();Check(reader.Read(10).Rows.Count==0,"Reset discards peak and combo counters");
    }
    static void VerifyMinimumDuration(string root){
        var o=new DpsOptions{Enabled=true};Check(o.HistoryMinimumSeconds==60,"Default minimum fight duration must be sixty seconds");var json=new JavaScriptSerializer();var migrated=DpsOptions.Read(json.Deserialize<Dictionary<string,object>>("{\"dps\":{\"Enabled\":true,\"HistoryMaxRecords\":12}}"));Check(migrated.HistoryMinimumSeconds==60&&migrated.HistoryMaxRecords==12,"Existing preferences migrate without losing their storage limit");o.HistoryMinimumSeconds=-1;o.Normalize();Check(o.HistoryMinimumSeconds==0,"Minimum duration can be disabled and cannot be negative");o.HistoryMinimumSeconds=99999;o.Normalize();Check(o.HistoryMinimumSeconds==3600,"Minimum duration is bounded");o.HistoryMinimumSeconds=60;
        double now=DpsHistory.UtcNow();string folder=Path.Combine(root,"history-duration-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string path=Path.Combine(folder,"combat-history.json");
        using(var store=new DpsHistory(folder,o)){store.Add(HistorySample(now,59.999));Check(store.Read().Count==0&&store.Revision==0&&!File.Exists(path),"Short fights must not cause history changes or disk writes");store.Add(HistorySample(now,60));Check(store.Read().Count==1,"Exactly sixty seconds is accepted");o.HistoryMinimumSeconds=90;store.Configure(o);store.Add(HistorySample(now+1,80));Check(store.Read().Count==1,"Changing minimum only filters future records");o.HistoryMinimumSeconds=0;store.Configure(o);store.Add(HistorySample(now+2,0));Check(store.Read().Count==2,"Zero seconds saves an instantaneous fight");store.Flush();}
        o.HistoryMinimumSeconds=60;using(var store=new DpsHistory(folder,o)){Check(store.Read().Count==2&&store.Read()[1].Players[0].HighestHit.HasValue&&store.Read()[1].Players[0].BackHits.HasValue,"Peak and tag metrics persist; existing short records are retained");string text=DpsHistory.Text(store.Read()[1],"es");Check(text.Contains("Golpe más alto")&&text.Contains("Espalda doble crítico")&&text.Contains("Frente perfecto"),"TXT exports localized peak and all combinations");}
