        var o=new DpsOptions{AutoHide=true,HideAfterSeconds=2,FadeSeconds=.2,SmoothingSeconds=.2};var s=DpsDesign.Sample();s.FirstImpact=1;s.LastImpact=100;var motion=new DpsMotion();motion.Set(s,o,0,100);motion.Step(0,false,o);motion.Step(.1,false,o);Check(motion.Opacity>.4&&motion.Opacity<.6&&motion.Ratios[1]>0&&motion.Ratios[1]<1,"Fade in and smooth growth");motion.Step(.2,false,o);Check(motion.Opacity>.999,"Fade reaches full opacity");
        double old=motion.Ratios[2];s.Rows[1].Damage=1000;motion.Set(s,o,.3,100.3);motion.Step(.3,false,o);motion.Step(.4,false,o);Check(motion.Ratios[2]<old&&motion.Ratios[2]>1000.0/38600,"Smooth shrinking bar");
        motion.Step(2.01,false,o);motion.Step(2.11,false,o);Check(motion.Opacity>.4&&motion.Opacity<.6,"Idle fade starts at deadline");s.LastImpact=102.11;motion.Set(s,o,2.11,102.11);motion.Step(2.11,false,o);motion.Step(2.16,false,o);Check(motion.Opacity>.7&&motion.Opacity<1,"New combat reverses fading");
        motion.Step(4.2,false,o);motion.Step(4.5,false,o);Check(motion.Opacity==0,"Hide completes");motion.Step(4.5,true,o);Check(motion.Opacity==1,"Unlocked widgets stay visible");o.AutoHide=false;motion.Step(5,false,o);Check(motion.Opacity==1,"Disabled auto hide stays visible");o.Smooth=false;motion.Step(5.1,false,o);Check(motion.Ratios[2]==1000.0/38600,"Disabling smoothing snaps to accurate ratio");o.HideAfterSeconds=double.NaN;o.FadeSeconds=double.PositiveInfinity;o.Normalize();Check(o.HideAfterSeconds==15&&o.FadeSeconds==.2,"Invalid animation settings normalized");
        o.AutoHide=true;var missing=new DpsSignal.Snapshot{NeedsIdentification=true,Status="Dash once to identify your character"};motion.Reset();motion.Set(missing,o,0,100);motion.Step(100,false,o);Check(motion.Opacity==1&&!motion.Animating,"Identification notice stays fully visible beyond inactivity deadline");missing.NeedsIdentification=false;missing.SelfActor=42;motion.Set(missing,o,101,201);motion.Step(101,false,o);motion.Step(101.3,false,o);Check(motion.Opacity==0,"Detecting character restores ordinary idle hiding");
    }
    internal static void Replay(string root,string file){var reader=new DpsSignal();reader.Configure(new DpsOptions{Enabled=true,Scope="global"});var serializer=new JavaScriptSerializer();double last=0;int frames=0;long maximumDamage=0;foreach(string line in File.ReadLines(file)){var r=serializer.Deserialize<Dictionary<string,object>>(line);string hex=(string)r["hex"];var bytes=new byte[hex.Length/2];for(int i=0;i<bytes.Length;i++)bytes[i]=Convert.ToByte(hex.Substring(i*2,2),16);last=Convert.ToDouble(r["ts"]);reader.Consume(bytes,0,bytes.Length,last,"replay");frames++;if(bytes.Length>1&&(bytes[0]==4||bytes[0]==5)&&bytes[1]==0x38){long total=0;foreach(var row in reader.Read(last).Rows)total+=row.Damage;maximumDamage=Math.Max(maximumDamage,total);}}
        File.WriteAllText(Path.Combine(root,"dps-replay-test.txt"),serializer.Serialize(new{frames=frames,maximumEncounterDamage=maximumDamage,lastSnapshot=DpsSignal.Export(reader.Read(last)),experimental=true}));Check(maximumDamage>0,"Replay did not produce attributed combat data");}
}
